package com.flippingfriend.companion;
import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementQuantityFillInputContextComposerTest {
 @Test public void bindsOrderedQuantitiesToSharedCurveHorizonAndSeason(){BuyReplacementQuantityGridCandidateSet g=grid();BuyReplacementCandidateFillInputContext f=fill();BuyReplacementQuantityFillInputContext r=new BuyReplacementQuantityFillInputContextComposer().compose(g,f,1.25,1100,1100);assertNotNull(r);assertSame(f.getFillCurve(),r.getFillCurve());assertEquals(f.getEffectiveHorizonHours(),r.getEffectiveHorizonHours(),0.0);assertEquals(1.25,r.getSeasonalMultiplier(),0.0);assertEquals(g.getCandidates().size(),r.getInputs().size());for(int i=0;i<r.getInputs().size();i++){BuyReplacementQuantityGridCandidate a=g.getCandidates().get(i);BuyReplacementQuantityFillInput x=r.getInputs().get(i);assertEquals(a.getSizeGridIndex(),x.getSizeGridIndex());assertEquals(a.getSizeShare(),x.getSizeShare(),0.0);assertEquals(a.getQuantity(),x.getQuantity());assertEquals(a.getBuyPrice(),x.getBuyPrice());assertEquals(a.getSellPrice(),x.getSellPrice());}try{r.getInputs().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableStaleAndInvalidSeasonFailClosed(){BuyReplacementQuantityFillInputContextComposer c=new BuyReplacementQuantityFillInputContextComposer();assertNull(c.compose(null,fill(),1,1100,1100));assertNull(c.compose(grid(),null,1,1100,1100));assertNull(c.compose(grid(),fill(),Double.NaN,1100,1100));assertNull(c.compose(grid(),fill(),1,1100,1221));}
 @Test public void contractsCarryNoEstimateEconomicsSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementQuantityFillInput.java","BuyReplacementQuantityFillInputContext.java"}){String x=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String forbidden:new String[]{"FillModel","FillEstimate","estimateBuy","estimateSell","isPlausible","correctedHours","expectedGpPerSlotHour","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(x.contains(forbidden));}}
 static BuyReplacementQuantityFillInputContext contextForCompanionTests(){return new BuyReplacementQuantityFillInputContextComposer().compose(grid(),fill(),1.0,1100,1100);} private static BuyReplacementQuantityGridCandidateSet grid(){return BuyReplacementQuantityGridComposerTest.quantityFillCandidateSetForCompanionTests();} private static BuyReplacementCandidateFillInputContext fill(){return BuyReplacementCandidateFillInputContextComposerTest.contextForCompanionTests();}
}
